{
  "type": "object",
  "properties": {
    "days": {
      "type": "integer",
      "default": 7,
      "description": "Days back to search"
    },
    "limit": {
      "type": "integer",
      "default": 50,
      "description": "Max posts to return"
    }
  }
}
