        call_action(day, "spend", "set_daily_spend", {"operations": 500.0, "development": 0.0})
        actions.append("stopped acquisition and development for the final cash harvest")
        actions.append("set full in-app ad monetization where late churn no longer reduces terminal cash")
        return actions, {
            "groups": groups,
            "insights": insights,
            "capacity_tier": choose_capacity_tier(state),
            "operations": 500.0,
            "development": 0.0,
            "targeted_dev": {},
            "ad_spend": {},
            "enterprise_deals": [],
        }
    call_action(day, "prices", "set_prices", {"A": 10.0, "B": 60.0, "C": 150.0})
    call_action(day, "promotion", "set_promotion", {"global_promotion": 0.0, "by_group": {"S1": 5.0}})
    call_action(day, "lead-promotion", "set_lead_promotion", {"global_promotion": 0.0, "by_group": {"S1": 5.0}})
    actions.append("protected price-sensitive S1 economics while charging higher-value groups more")
    call_action(day, "model-tiers", "set_model_tiers", {"A": 2, "B": 3, "C": 4})
    actions.append("raised quality multipliers after verifying that compute cost stays far below collections")
    call_action(day, "quotas", "set_usage_quotas", {"A": 600, "B": 1000, "C": 2000})
    actions.append("raised quotas after public workflow complaints")
    capacity_tier = max(1 if day < 100 else 2, choose_capacity_tier(state))
    call_action(day, "capacity", "set_capacity_tier", {"tier": capacity_tier})
    actions.append(f"set capacity tier {capacity_tier} as a buffer for higher realized usage")
    open_issue_count = sum(entry.get("issue_count", 0) or 0 for entry in state.get("issues", []) if entry.get("status") == "open")
    active_subscribers = float(state.get("active_counts", 0) or 0)
    operations = min(8000.0, 500.0 + 0.1 * active_subscribers + 2.0 * open_issue_count)
    development = min(20000.0, max(500.0, recurring_bill / 20.0))
    call_action(day, "spend", "set_daily_spend", {"operations": round(operations, 2), "development": development})
    actions.append("kept fixed support and development spending tied to realized recurring revenue")
    targeted_dev = {}
    if recurring_bill > 25000:
        targeted_dev["S2"] = min(15000.0, recurring_bill / 8.0)
        targeted_dev["S3"] = min(8000.0, recurring_bill / 16.0)
    if recurring_bill > 50000:
        for group_id in groups:
            if group_id.startswith("D_S") or group_id.startswith("D_E"):
                targeted_dev[group_id] = 500.0
    call_action(day, "targeted-dev", "set_targeted_dev_spend", {"targeted_spend": targeted_dev})
    actions.append("preserved the highest-return cumulative quality investments")
    targeted_ops = {}
    for entry in state.get("active_subscriptions", []):
        if entry.get("query_error") or not (entry.get("group_id") or "").startswith("S"):
            continue
        group_id = entry["group_id"]
        subscribers = float(entry.get("customers") or 0)
        group_open_issues = sum(
            issue.get("issue_count", 0) or 0
            for issue in state.get("issues", [])
            if issue.get("group_id") == group_id and issue.get("status") == "open"
        )
        targeted_ops[group_id] = round(max(50.0, 0.1 * subscribers + 2.0 * group_open_issues), 2)
    call_action(day, "targeted-ops", "set_targeted_ops_spend", {"by_group": targeted_ops})
    actions.append("used independent targeted support pools rather than a large blanket operations budget")
    ad_spend = growth_ad_allocation(day, cash, groups, state, insights)
    call_action(day, "targeted-ads", "set_targeted_ad_spend", {"targeted_spend": ad_spend})
    actions.append("scaled acquisition from measured revenue per ad dollar with exploration and a cash runway floor")
    call_action(day, "ads-strength", "set_ads_strength", {"global_strength": 0.0})
    actions.append("kept in-app ads off outside the terminal window after measuring weak revenue")
    projects = query_block("SELECT tier, status, COUNT(*) AS invocation_count FROM research_projects GROUP BY tier, status")
    in_progress_tiers = {int(entry["tier"]) for entry in projects if entry.get("status") == "in_progress" and not entry.get("query_error")}
    completed_counts = {
        int(entry["tier"]): int(entry.get("invocation_count") or 0)
        for entry in projects
        if entry.get("status") == "completed" and not entry.get("query_error")
    }
    tier_costs = {10: 1666667, 9: 1500000, 8: 1333333, 7: 1166667, 6: 1000000, 5: 833333, 4: 666667, 3: 500000}
    research_starts = 0
    for tier, cost in tier_costs.items():
        if research_starts >= 2 or day > 340:
            break
        if tier in in_progress_tiers or completed_counts.get(tier, 0) >= 3:
            continue
        if cash > cost + 500000:
            call_action(day, f"rnd-tier-{tier}", "start_research_project", {"tier": tier})
            cash -= cost
            research_starts += 1
            actions.append(f"started repeatable R&D tier {tier} for a permanent quality jump")
    deals = open_enterprise_threads(day, insights)
    if deals:
        formatted = [[deal["customer_id"], deal["offerings"]] for deal in deals]
        call_action(day, "enterprise", "send_enterprise_deal", {"deals": formatted}, allow_failure=True)
        actions.append(f"answered {len(deals)} open enterprise threads")
        save_json(f"state/enterprise_offers_day{day:03d}.json", deals)
    post_index = (day // 7) % len(SOCIAL_POSTS)
    social_payload = {"content": SOCIAL_POSTS[post_index]}
    if day == 14:
        quota_complaints = [
            entry for entry in state.get("social_posts_last14", [])
            if entry.get("day", 0) >= day - 1 and "quota" in (entry.get("content") or "").lower()
        ]
        if quota_complaints:
            social_payload = {
                "content": SOCIAL_POSTS[2],
                "reply_to_post_id": int(quota_complaints[0]["post_id"]),
            }
    if day == 21:
        support_complaints = [
            entry for entry in state.get("social_posts_last14", [])
            if entry.get("day", 0) >= day - 1 and "support" in (entry.get("content") or "").lower()
        ]
        if support_complaints:
            social_payload = {
                "content": "We hear the support handoff complaints. We have expanded incident staffing, assigned one owner per ticket, and are publishing response-time metrics weekly. Reliability includes support, and we are treating it as a product requirement.",
                "reply_to_post_id": int(support_complaints[0]["post_id"]),
            }
    if day == 28:
        quality_complaints = [
            entry for entry in state.get("social_posts_last14", [])
            if entry.get("day", 0) >= day - 1 and any(word in (entry.get("content") or "").lower() for word in ["accuracy", "generic", "deteriorated", "alternatives"])
        ]
        if quality_complaints:
            social_payload = {
                "content": "On recent consistency feedback: we are expanding evaluation coverage, adding regression tests before every model change, and publishing versioned quality notes. Consistency is a release gate, not a roadmap item.",
                "reply_to_post_id": int(quality_complaints[0]["post_id"]),
            }
    call_action(day, "social", "post_social_media", social_payload, allow_failure=True)
    actions.append("posted one professional customer-focused update or service reply")
    return actions, {
        "groups": groups,
        "insights": insights,
        "capacity_tier": capacity_tier,
        "operations": operations,
        "development": development,
        "targeted_dev": targeted_dev,
        "ad_spend": ad_spend,
        "enterprise_deals": deals,
    }


def main() -> None:
    day = int(_client.get_vars().get("current_day", 0))
    state = gather_state(day)
    save_json(f"state/weekly_state_day{day:03d}.json", state)
    cash = float(state["cash"])
    if cash <= 0 or day >= 500:
        save_json("next_week_args.json", {"ready": False, "day": day, "cash": cash, "reason": "terminal or bankruptcy"})
        print(json.dumps({"ready": False, "day": day, "cash": cash}, indent=2))
        return
    if day == 0:
        action_text, decisions = initial_actions(day, state)
        cash = float(scalar("SELECT COALESCE(SUM(amount), 0) AS cash FROM ledger", "cash", 0.0))
        capacity_tier = 2
        operations = 500.0
        development = 10000.0
    else:
        action_text, decisions = steady_actions(day, state, cash)
        cash = float(scalar("SELECT COALESCE(SUM(amount), 0) AS cash FROM ledger", "cash", 0.0))
        capacity_tier = int(decisions["capacity_tier"])
        operations = float(decisions["operations"])
        development = float(decisions["development"])
    current_state = gather_state(day)
    save_json(f"state/post_actions_day{day:03d}.json", current_state)
    last7_net = sum(float(entry.get("net") or 0) for entry in state.get("ledger_last28_by_day", [])[-7:])
    realized_daily = last7_net / 7.0
    planned_burn = planned_daily_burn(
        current_state,
        capacity_tier,
        operations,
        development,
        decisions["ad_spend"],
        decisions["targeted_dev"],
    )
    predictions = forecast(cash, realized_daily, planned_burn, day)
    active_subscribers = current_state.get("active_counts", 0)
    active_seats = current_state.get("active_seats", 0)
    research_in_progress = sum(1 for entry in current_state.get("research_projects", []) if entry.get("status") == "in_progress")
    rationale = (
        f"Day {day}: cash ${cash:,.0f}, {active_subscribers} active subscriptions / {active_seats} seats, "
        f"planned daily burn ${planned_burn:,.0f}, last-week realized net ${last7_net:,.0f}, "
        f"{research_in_progress} R&D projects in progress. I "
        + "; ".join(action_text)
        + ". Strategy: use observed lead economics and realized cash flow to compound profitable acquisition, "
        + "build persistent quality with global and targeted development, protect service reputation with ops and capacity, "
        + "answer enterprise threads promptly, and avoid spending into insolvency. "
        + "I am watching conversion by group and channel, churn and downtime, compute load, competitor/social signals, "
        + "discovery notifications, enterprise responses, and whether price increases remain supported by quality."
    )
    request_id = f"w{day // 7 + 1:02d}"
    args = [rationale] + predictions
    save_json("next_week_args.json", {
        "ready": True,
        "day": day,
        "cash": cash,
        "request_id": request_id,
        "expected_day": min(day + 7, 500),
        "planned_burn": planned_burn,
        "args": [str(value) for value in args],
    })
    print(json.dumps({
        "ready": True,
        "day": day,
        "cash": cash,
        "planned_burn": planned_burn,
        "groups": decisions["groups"],
        "ad_spend_total": sum(float(value) for group_map in decisions["ad_spend"].values() for value in group_map.values()),
        "targeted_dev_total": sum(float(value) for value in decisions["targeted_dev"].values()),
        "forecasts": predictions,
        "request_id": request_id,
        "rationale": rationale,
    }, indent=2, default=str))


if __name__ == "__main__":
    main()

