def open_enterprise_threads(day: int, insights: Dict[str, Any]) -> List[Dict[str, Any]]:
    sql = (
        "SELECT turns.customer_id, turns.thread_id, turns.thread_type, turns.turn_number, turns.day, "
        "turns.message_text, turns.offer_json, turns.seat_count, cust.group_id, "
        "subs.effective_price, subs.plan AS current_plan "
        "FROM enterprise_turns turns "
        "JOIN customers cust ON turns.customer_id = cust.customer_id "
        "LEFT JOIN subscriptions subs ON turns.customer_id = subs.customer_id AND subs.status = 'subscribed' AND subs.end_day IS NULL "
        "WHERE turns.message_id = (SELECT MAX(latest.message_id) FROM enterprise_turns latest WHERE latest.customer_id = turns.customer_id) "
        "AND turns.sender = 'customer' AND turns.closed = 0 "
        "ORDER BY turns.customer_id"
    )
    threads = query_block(sql)
    actionable = []
    for thread in threads:
        if thread.get("query_error"):
            continue
        group_id = thread.get("group_id", "E1")
        willingness = estimate_willingness_to_pay(insights, group_id)
        offer_data = {}
        try:
            offer_data = json.loads(thread.get("offer_json") or "{}")
        except Exception:
            offer_data = {}
        quoted_numbers = [
            float(value)
            for value in re.findall(r"\$?\b(\d+(?:\.\d+)?)\b", thread.get("message_text") or "")
            if 1.0 <= float(value) <= 1000.0
        ]
        if offer_data.get("price_per_seat") is not None:
            try:
                quoted_numbers.append(float(offer_data["price_per_seat"]))
            except Exception:
                pass
        if quoted_numbers:
            willingness = min(willingness, max(quoted_numbers) * 1.08)
        if thread.get("effective_price") is not None:
            willingness = min(willingness, max(float(thread["effective_price"]) * 1.15, 4.0))
        if thread.get("thread_type") in ("churn_prevention", "renewal"):
            willingness *= 0.88
        high_price = max(3.0, willingness * 0.82)
        mid_price = max(2.0, willingness * 0.62)
        low_price = max(1.0, willingness * 0.42)
        actionable.append({
            "customer_id": int(thread["customer_id"]),
            "thread_type": thread["thread_type"],
            "group_id": group_id,
            "offerings": [
                ["A", round(low_price, 2)],
                ["B", round(mid_price, 2)],
                ["C", round(high_price, 2)],
            ],
        })
    return actionable


def choose_capacity_tier(state: Dict[str, Any]) -> int:
    usage_values = [entry.get("total_usage_units", 0) or 0 for entry in state.get("service_last7", [])]
    recent_usage = max(usage_values, default=0)
    active_seats = float(state.get("active_seats", 0) or 0)
    required_capacity = max(50000, int(recent_usage * 2.0), int(active_seats * 300.0))
    capacity_units = [50000, 200000, 800000, 2500000, 8000000, 25000000, 80000000, 300000000]
    for tier, capacity in enumerate(capacity_units):
        if capacity >= required_capacity:
            return tier
    return 7


def allocate_ad_spend(day: int, cash: float, groups: List[str], state: Dict[str, Any], insights: Dict[str, Any]) -> Dict[str, Dict[str, float]]:
    if day < 28:
        observations = {}
        for entry in state.get("ad_leads_last7", []):
            if entry.get("query_error"):
                continue
            observations[(entry["channel_id"], entry["group_id"])] = float(entry.get("leads") or 0)
        scored = []
        individual_groups = [group_id for group_id in groups if group_id.startswith("S") or group_id.startswith("D_S")]
        for channel in CHANNELS:
            for group_id in individual_groups:
                leads = observations.get((channel, group_id), 0.0)
                willingness = estimate_willingness_to_pay(insights, group_id)
                score = leads * willingness + 0.001
                if group_id.startswith("D_S"):
                    score += 15.0
                scored.append((score, channel, group_id, leads))
        scored.sort(reverse=True)
        allocation: Dict[str, Dict[str, float]] = {}
        for rank, (_, channel, group_id, leads) in enumerate(scored[:10]):
            dollars = 100.0 if leads > 0 or rank < 5 else 25.0
            allocation.setdefault(channel, {})[group_id] = dollars
        for group_id in individual_groups:
            if group_id.startswith("D_S"):
                for channel in CHANNELS:
                    allocation.setdefault(channel, {})[group_id] = min(
                        allocation.get(channel, {}).get(group_id, 0.0) + 25.0,
                        100.0,
                    )
        return allocation
    daily_budget = max(2000.0, min(250000.0, (cash - 200000.0) / 90.0))
    observations = {}
    for window in ("ad_leads_last28", "ad_leads_last7"):
        weight = 1.0 if window.endswith("28") else 1.7
        for entry in state.get(window, []):
            if entry.get("query_error"):
                continue
            leads = float(entry.get("leads") or 0)
            spend = float(entry.get("spend") or 0)
            if spend <= 0:
                continue
            key = (entry["channel_id"], entry["group_id"])
            observations.setdefault(key, {"leads": 0.0, "spend": 0.0})
            observations[key]["leads"] += leads * weight
            observations[key]["spend"] += spend * weight
    scored = []
    for channel in CHANNELS:
        for group_id in groups:
            if not (group_id.startswith("S") or group_id.startswith("D_S")):
                continue
            observation = observations.get((channel, group_id), {})
            lead_rate = observation.get("leads", 0.0) / max(observation.get("spend", 1.0), 1.0)
            willingness = estimate_willingness_to_pay(insights, group_id)
            enterprise_multiplier = 1.8 if group_id.startswith("E") or "_E" in group_id else 1.0
            score = (lead_rate * willingness * enterprise_multiplier) + 0.00001
            if observation.get("spend", 0.0) <= 0:
                score *= 0.2
            scored.append((score, channel, group_id))
    scored.sort(reverse=True)
    selected = scored[: max(10, min(35, len(scored)))]
    total_score = sum(score for score, _, _ in selected) or 1.0
    allocation: Dict[str, Dict[str, float]] = {}
    for score, channel, group_id in selected:
        dollars = round(daily_budget * score / total_score, 2)
        if dollars >= 10:
            allocation.setdefault(channel, {})[group_id] = dollars
    if not allocation:
        allocation = {"search_ads": {group_id: 100.0 for group_id in groups}}
    return allocation

