def query_block(sql: str) -> List[Dict[str, Any]]:
    try:
        return rows(sql)
    except Exception as exc:
        return [{"query_error": str(exc), "sql": sql}]


def gather_state(day: int) -> Dict[str, Any]:
    lookback_short = max(0, day - 7)
    lookback_month = max(0, day - 28)
    return {
        "day": day,
        "cash": scalar("SELECT COALESCE(SUM(amount), 0) AS cash FROM ledger", "cash", 0.0),
        "ledger_last7_by_category": query_block(
            f"SELECT category, ROUND(SUM(amount), 2) AS total FROM ledger WHERE day > {lookback_short} GROUP BY category ORDER BY total"
        ),
        "ledger_last28_by_day": query_block(
            f"SELECT day, ROUND(SUM(amount), 2) AS net FROM ledger WHERE day > {lookback_month} GROUP BY day ORDER BY day"
        ),
        "active_subscriptions": query_block(
            "SELECT cust.group_id, subs.plan, subs.status, COUNT(*) AS customers, "
            "COALESCE(SUM(subs.seat_count), 0) AS seats, "
            "ROUND(AVG(subs.effective_price), 2) AS avg_price "
            "FROM subscriptions subs JOIN customers cust ON subs.customer_id = cust.customer_id "
            "WHERE subs.status = 'subscribed' AND subs.end_day IS NULL "
            "GROUP BY cust.group_id, subs.plan, subs.status ORDER BY customers DESC"
        ),
        "subscription_changes_last7": query_block(
            f"SELECT cust.group_id, subs.status, subs.plan, COUNT(*) AS events "
