def known_groups(state: Dict[str, Any]) -> List[str]:
    overview = state.get("market_overview", {})
    if not overview.get("ok"):
        return BASE_GROUPS[:]
    groups = [entry["group_id"] for entry in overview["data"].get("known_groups", [])]
    return groups or BASE_GROUPS[:]


def undiscovered_count(state: Dict[str, Any]) -> int:
    overview = state.get("market_overview", {})
    if not overview.get("ok"):
        return 20
    return int(overview["data"].get("undiscovered_count", 20))


def monthly_recurring_bill(state: Dict[str, Any]) -> float:
    total = 0.0
    for entry in state.get("active_subscriptions", []):
        if entry.get("query_error"):
            continue
        total += float(entry.get("seats") or 0) * float(entry.get("avg_price") or 0)
    return total


def growth_ad_budget(cash: float, recurring_bill: float, day: int) -> float:
    if day >= 469:
        return 0.0
    revenue_budget = min(50000.0, max(1000.0, recurring_bill / 10.0))
    if day > 420:
        revenue_budget *= max(0.0, (483.0 - day) / 63.0)
    cash_budget = max(750.0, 1000.0 + max(0.0, cash - 200000.0) / 80.0)
    return min(50000.0, revenue_budget, cash_budget)


def observed_ad_pair_scores(day: int, groups: List[str], state: Dict[str, Any], insights: Dict[str, Any]) -> Dict[Tuple[str, str], float]:
    scores: Dict[Tuple[str, str], float] = {}
    lookback = max(0, day - 7)
    subscription_sql = (
        "SELECT cust.group_id, cust.acquisition_source, "
        "COALESCE(SUM(subs.effective_price * subs.seat_count), 0) AS monthly_bill, "
        "COUNT(*) AS subscribers FROM subscriptions subs "
        "JOIN customers cust ON subs.customer_id = cust.customer_id "
        f"WHERE subs.start_day > {lookback} AND subs.status = 'subscribed' AND subs.end_day IS NULL "
        "GROUP BY cust.group_id, cust.acquisition_source"
    )
    for entry in query_block(subscription_sql):
        if entry.get("query_error") or entry.get("acquisition_source") not in CHANNELS:
            continue
        key = (entry["acquisition_source"], entry["group_id"])
        spend = 0.0
        for lead_entry in state.get("ad_leads_last7", []):
            if lead_entry.get("channel_id") == key[0] and lead_entry.get("group_id") == key[1]:
                spend = float(lead_entry.get("spend") or 0)
                break
        remaining_months = max(1.0, (500 - day) / 30.0)
        lifetime_value = float(entry.get("monthly_bill") or 0) * min(16.0, remaining_months)
        scores[key] = (lifetime_value + 2.0 * float(entry.get("subscribers") or 0)) / max(100.0, spend)
    for entry in state.get("ad_leads_last28", []):
        if entry.get("query_error"):
            continue
        key = (entry.get("channel_id"), entry.get("group_id"))
        if key[0] not in CHANNELS or key[1] not in groups:
            continue
        lead_rate = float(entry.get("leads") or 0) / max(1.0, float(entry.get("spend") or 0))
        willingness = estimate_willingness_to_pay(insights, key[1])
        prior = 0.0008 * lead_rate * willingness
        scores[key] = max(scores.get(key, 0.0), prior)
    for channel in CHANNELS:
        for group_id in groups:
            if not (group_id.startswith("S") or group_id.startswith("D_S")):
                continue
            key = (channel, group_id)
            if key not in scores:
                scores[key] = 0.03 if group_id.startswith("D_S") else 0.005
    return scores


def growth_ad_allocation(day: int, cash: float, groups: List[str], state: Dict[str, Any], insights: Dict[str, Any]) -> Dict[str, Dict[str, float]]:
    recurring_bill = monthly_recurring_bill(state)
    budget = growth_ad_budget(cash, recurring_bill, day)
    scores = observed_ad_pair_scores(day, groups, state, insights)
    ranked = sorted(scores.items(), key=lambda item: item[1], reverse=True)
    allocation: Dict[str, Dict[str, float]] = {}

    def add_pair(channel: str, group_id: str, dollars: float) -> None:
        if dollars <= 0:
            return
        channel_map = allocation.setdefault(channel, {})
        channel_map[group_id] = round(channel_map.get(group_id, 0.0) + dollars, 2)

    core_pair = ("content_marketing", "S1")
    add_pair(core_pair[0], core_pair[1], 0.35 * budget)
    top_pairs = [item for item in ranked if item[0] != core_pair][:3]
    top_total = sum(score for _, score in top_pairs) or 1.0
    for (channel, group_id), score in top_pairs:
        add_pair(channel, group_id, 0.55 * budget * score / top_total)
    observed_pairs = [key for key in scores if scores[key] > 0.005]
    if observed_pairs:
        for channel, group_id in observed_pairs:
            add_pair(channel, group_id, 0.08 * budget / len(observed_pairs))
    hidden_pairs = [
        (channel, group_id)
        for channel in CHANNELS
        for group_id in groups
        if group_id.startswith("D_S")
    ]
    if hidden_pairs:
        for channel, group_id in hidden_pairs:
            add_pair(channel, group_id, 0.02 * budget / len(hidden_pairs))
    if not allocation:
        for channel in CHANNELS:
            for group_id in groups:
                if group_id.startswith("S") or group_id.startswith("D_S"):
                    add_pair(channel, group_id, budget / (5 * max(1, len(groups))))
    return allocation


def group_insights(groups: List[str]) -> Dict[str, Dict[str, Any]]:
    result = {}
    for group_id in groups:
        result[group_id] = read_tool("get_group_insights", {"group_id": group_id})
    return result


def estimate_willingness_to_pay(insights: Dict[str, Any], group_id: str) -> float:
    entry = insights.get(group_id, {})
    if not entry.get("ok"):
        return 60.0
    estimates = entry["data"].get("estimates", {})
    value = estimates.get("willingness_to_pay", 60.0)
    try:
        return max(5.0, float(value))
    except Exception:
        return 60.0


def open_enterprise_threads(day: int, insights: Dict[str, Any]) -> List[Dict[str, Any]]:
    sql = (
        "SELECT turns.customer_id, turns.thread_id, turns.thread_type, turns.turn_number, turns.day, "
        "turns.message_text, turns.offer_json, turns.seat_count, cust.group_id, "
        "subs.effective_price, subs.plan AS current_plan "
        "FROM enterprise_turns turns "
        "JOIN customers cust ON turns.customer_id = cust.customer_id "
        "LEFT JOIN subscriptions subs ON turns.customer_id = subs.customer_id AND subs.status = 'subscribed' AND subs.end_day IS NULL "
        "WHERE turns.message_id = (SELECT MAX(latest.message_id) FROM enterprise_turns latest WHERE latest.customer_id = turns.customer_id) "
        "AND turns.sender = 'customer' AND turns.closed = 0 "
        "ORDER BY turns.customer_id"
    )
    threads = query_block(sql)
    actionable = []
    for thread in threads:
        if thread.get("query_error"):
            continue
        group_id = thread.get("group_id", "E1")
        willingness = estimate_willingness_to_pay(insights, group_id)
        offer_data = {}
        try:
            offer_data = json.loads(thread.get("offer_json") or "{}")
        except Exception:
            offer_data = {}
        quoted_numbers = [
            float(value)
            for value in re.findall(r"\$?\b(\d+(?:\.\d+)?)\b", thread.get("message_text") or "")
            if 1.0 <= float(value) <= 1000.0
        ]
        if offer_data.get("price_per_seat") is not None:
            try:
                quoted_numbers.append(float(offer_data["price_per_seat"]))
            except Exception:
                pass
        if quoted_numbers:
            willingness = min(willingness, max(quoted_numbers) * 1.08)
        if thread.get("effective_price") is not None:
            willingness = min(willingness, max(float(thread["effective_price"]) * 1.15, 4.0))
        if thread.get("thread_type") in ("churn_prevention", "renewal"):
            willingness *= 0.88
        high_price = max(3.0, willingness * 0.82)
        mid_price = max(2.0, willingness * 0.62)
        low_price = max(1.0, willingness * 0.42)
        actionable.append({
            "customer_id": int(thread["customer_id"]),
            "thread_type": thread["thread_type"],
            "group_id": group_id,
            "offerings": [
                ["A", round(low_price, 2)],
                ["B", round(mid_price, 2)],
                ["C", round(high_price, 2)],
            ],
        })
    return actionable


def choose_capacity_tier(state: Dict[str, Any]) -> int:
    usage_values = [entry.get("total_usage_units", 0) or 0 for entry in state.get("service_last7", [])]
    recent_usage = max(usage_values, default=0)
    required_capacity = max(50000, int(recent_usage * 1.3))
    capacity_units = [50000, 200000, 800000, 2500000, 8000000, 25000000, 80000000, 300000000]
    for tier, capacity in enumerate(capacity_units):
        if capacity >= required_capacity:
            return tier
    return 7


def allocate_ad_spend(day: int, cash: float, groups: List[str], state: Dict[str, Any], insights: Dict[str, Any]) -> Dict[str, Dict[str, float]]:
    if day < 28:
        observations = {}
        for entry in state.get("ad_leads_last7", []):
            if entry.get("query_error"):
                continue
            observations[(entry["channel_id"], entry["group_id"])] = float(entry.get("leads") or 0)
        scored = []
        individual_groups = [group_id for group_id in groups if group_id.startswith("S") or group_id.startswith("D_S")]
        for channel in CHANNELS:
            for group_id in individual_groups:
                leads = observations.get((channel, group_id), 0.0)
                willingness = estimate_willingness_to_pay(insights, group_id)
                score = leads * willingness + 0.001
                if group_id.startswith("D_S"):
                    score += 15.0
                scored.append((score, channel, group_id, leads))
        scored.sort(reverse=True)
        allocation: Dict[str, Dict[str, float]] = {}
        for rank, (_, channel, group_id, leads) in enumerate(scored[:10]):
            dollars = 100.0 if leads > 0 or rank < 5 else 25.0
            allocation.setdefault(channel, {})[group_id] = dollars
        for group_id in individual_groups:
            if group_id.startswith("D_S"):
                for channel in CHANNELS:
                    allocation.setdefault(channel, {})[group_id] = min(
                        allocation.get(channel, {}).get(group_id, 0.0) + 25.0,
                        100.0,
                    )
        return allocation
    daily_budget = max(2000.0, min(250000.0, (cash - 200000.0) / 90.0))
    observations = {}
    for window in ("ad_leads_last28", "ad_leads_last7"):
        weight = 1.0 if window.endswith("28") else 1.7
        for entry in state.get(window, []):
            if entry.get("query_error"):
                continue
            leads = float(entry.get("leads") or 0)
            spend = float(entry.get("spend") or 0)
            if spend <= 0:
                continue
            key = (entry["channel_id"], entry["group_id"])
            observations.setdefault(key, {"leads": 0.0, "spend": 0.0})
            observations[key]["leads"] += leads * weight
            observations[key]["spend"] += spend * weight
    scored = []
    for channel in CHANNELS:
        for group_id in groups:
            if not (group_id.startswith("S") or group_id.startswith("D_S")):
                continue
            observation = observations.get((channel, group_id), {})
            lead_rate = observation.get("leads", 0.0) / max(observation.get("spend", 1.0), 1.0)
            willingness = estimate_willingness_to_pay(insights, group_id)
            enterprise_multiplier = 1.8 if group_id.startswith("E") or "_E" in group_id else 1.0
            score = (lead_rate * willingness * enterprise_multiplier) + 0.00001
            if observation.get("spend", 0.0) <= 0:
                score *= 0.2
            scored.append((score, channel, group_id))
    scored.sort(reverse=True)
    selected = scored[: max(10, min(35, len(scored)))]
    total_score = sum(score for score, _, _ in selected) or 1.0
    allocation: Dict[str, Dict[str, float]] = {}
    for score, channel, group_id in selected:
        dollars = round(daily_budget * score / total_score, 2)
        if dollars >= 10:
            allocation.setdefault(channel, {})[group_id] = dollars
    if not allocation:
        allocation = {"search_ads": {group_id: 100.0 for group_id in groups}}
    return allocation


def planned_daily_burn(state: Dict[str, Any], capacity_tier: int, operations: float, development: float, ad_spend: Dict[str, Dict[str, float]], targeted_dev: Dict[str, float]) -> float:
    latest = state.get("config_history", [{}])[0] if state.get("config_history") else {}
    advertising = sum(float(value) for group_map in ad_spend.values() for value in group_map.values())
    return (
        advertising
        + operations
        + development
        + sum(float(value) for value in targeted_dev.values())
        + float(CAPACITY_COSTS.get(capacity_tier, 85))
        + float(latest.get("spend_advertising", 0) or 0) * 0.0
    )


def forecast(cash: float, realized_daily: float, planned_burn: float, day: int) -> List[str]:
    baseline = realized_daily if day >= 7 else -planned_burn
    if day >= 7:
        baseline = 0.65 * realized_daily - 0.35 * planned_burn * 0.15
    bounds = [
        (7, 0.70, 1.5, cash * 0.65, cash * 1.7),
        (28, 0.40, 2.5, cash * 0.70, max(3.0 * cash, 2000000.0)),
        (84, 0.10, 5.0, max(1.2 * cash, 1500000.0), max(8.0 * cash, 10000000.0)),
        (182, 0.02, 10.0, max(3.0 * cash, 4000000.0), max(15.0 * cash, 25000000.0)),
    ]
    result = []
    for horizon, lower_factor, upper_factor, point_floor, upper_floor in bounds:
        linear = cash + baseline * horizon
        acceleration = max(0.0, baseline) * horizon * (horizon / 56.0)
        point = max(0.0, linear + acceleration, point_floor)
        lower = max(0.0, point * lower_factor)
        upper = max(1.0, point * upper_factor, upper_floor, point)
        point = min(max(point, lower), upper)
        result.extend([f"{point:.2f}", f"{lower:.2f}", f"{upper:.2f}"])
    return result


