def monthly_recurring_bill(state: Dict[str, Any]) -> float:
    total = 0.0
    for entry in state.get("active_subscriptions", []):
        if entry.get("query_error"):
            continue
        total += float(entry.get("seats") or 0) * float(entry.get("avg_price") or 0)
    return total


def growth_ad_budget(cash: float, recurring_bill: float, day: int) -> float:
    if day >= 469:
        return 0.0
    revenue_budget = min(50000.0, max(1000.0, recurring_bill / 10.0))
    if day > 420:
        revenue_budget *= max(0.0, (483.0 - day) / 63.0)
    cash_budget = max(750.0, 1000.0 + max(0.0, cash - 200000.0) / 80.0)
    return min(50000.0, revenue_budget, cash_budget)


def observed_ad_pair_scores(day: int, groups: List[str], state: Dict[str, Any], insights: Dict[str, Any]) -> Dict[Tuple[str, str], float]:
    scores: Dict[Tuple[str, str], float] = {}
    lookback = max(0, day - 7)
    subscription_sql = (
        "SELECT cust.group_id, cust.acquisition_source, "
        "COALESCE(SUM(subs.effective_price * subs.seat_count), 0) AS monthly_bill, "
        "COUNT(*) AS subscribers FROM subscriptions subs "
        "JOIN customers cust ON subs.customer_id = cust.customer_id "
        f"WHERE subs.start_day > {lookback} AND subs.status = 'subscribed' AND subs.end_day IS NULL "
        "GROUP BY cust.group_id, cust.acquisition_source"
    )
    for entry in query_block(subscription_sql):
        if entry.get("query_error") or entry.get("acquisition_source") not in CHANNELS:
            continue
        key = (entry["acquisition_source"], entry["group_id"])
        spend = 0.0
        for lead_entry in state.get("ad_leads_last7", []):
            if lead_entry.get("channel_id") == key[0] and lead_entry.get("group_id") == key[1]:
                spend = float(lead_entry.get("spend") or 0)
                break
        remaining_months = max(1.0, (500 - day) / 30.0)
        lifetime_value = float(entry.get("monthly_bill") or 0) * min(16.0, remaining_months)
        scores[key] = (lifetime_value + 2.0 * float(entry.get("subscribers") or 0)) / max(100.0, spend)
    for entry in state.get("ad_leads_last28", []):
        if entry.get("query_error"):
            continue
        key = (entry.get("channel_id"), entry.get("group_id"))
        if key[0] not in CHANNELS or key[1] not in groups:
            continue
        lead_rate = float(entry.get("leads") or 0) / max(1.0, float(entry.get("spend") or 0))
        willingness = estimate_willingness_to_pay(insights, key[1])
        prior = 0.0008 * lead_rate * willingness
        scores[key] = max(scores.get(key, 0.0), prior)
    for channel in CHANNELS:
        for group_id in groups:
            if not (group_id.startswith("S") or group_id.startswith("D_S")):
                continue
            key = (channel, group_id)
            if key not in scores:
                scores[key] = 0.03 if group_id.startswith("D_S") else 0.005
    return scores


def growth_ad_allocation(day: int, cash: float, groups: List[str], state: Dict[str, Any], insights: Dict[str, Any]) -> Dict[str, Dict[str, float]]:
    recurring_bill = monthly_recurring_bill(state)
    budget = growth_ad_budget(cash, recurring_bill, day)
    scores = observed_ad_pair_scores(day, groups, state, insights)
    ranked = sorted(scores.items(), key=lambda item: item[1], reverse=True)
    allocation: Dict[str, Dict[str, float]] = {}

    def add_pair(channel: str, group_id: str, dollars: float) -> None:
        if dollars <= 0:
            return
        channel_map = allocation.setdefault(channel, {})
        channel_map[group_id] = round(channel_map.get(group_id, 0.0) + dollars, 2)

    core_pair = ("content_marketing", "S1")
    add_pair(core_pair[0], core_pair[1], 0.35 * budget)
    top_pairs = [item for item in ranked if item[0] != core_pair][:3]
    top_total = sum(score for _, score in top_pairs) or 1.0
    for (channel, group_id), score in top_pairs:
        add_pair(channel, group_id, 0.55 * budget * score / top_total)
    observed_pairs = [key for key in scores if scores[key] > 0.005]
    if observed_pairs:
        for channel, group_id in observed_pairs:
            add_pair(channel, group_id, 0.08 * budget / len(observed_pairs))
    hidden_pairs = [
        (channel, group_id)
        for channel in CHANNELS
        for group_id in groups
        if group_id.startswith("D_S")
    ]
    if hidden_pairs:
        for channel, group_id in hidden_pairs:
            add_pair(channel, group_id, 0.02 * budget / len(hidden_pairs))
    if not allocation:
        for channel in CHANNELS:
            for group_id in groups:
                if group_id.startswith("S") or group_id.startswith("D_S"):
                    add_pair(channel, group_id, budget / (5 * max(1, len(groups))))
    return allocation


