    result = {}
    for group_id in groups:
        result[group_id] = read_tool("get_group_insights", {"group_id": group_id})
    return result


def estimate_willingness_to_pay(insights: Dict[str, Any], group_id: str) -> float:
    entry = insights.get(group_id, {})
    if not entry.get("ok"):
        return 60.0
    estimates = entry["data"].get("estimates", {})
    value = estimates.get("willingness_to_pay", 60.0)
    try:
        return max(5.0, float(value))
    except Exception:
        return 60.0


